SELECT c.id, c.news_id, c.user_id, c.parent_id, c.to_user_id, c.content, c.status, c.create_time, u.username, c.like_count, (SELECT COUNT(1) FROM comment child WHERE child.root_comment_id = c.id AND child.status = 1) AS children FROM comment c LEFT JOIN user u ON c.user_id = u.id WHERE c.id IN
